from pathlib import Path
p=Path('app/src/main/java/com/suikang/sales/PdfQuotationExporter.java')
s=p.read_text()
old='''    private static Bitmap load(S s,Models.OrderItem it){\n        Bitmap b=loadRefs(s.ctx,it.imageUri,it.imageAsset);\n        if(b!=null)return b;\n        Models.Product p=findProduct(s.products,it);\n        if(p!=null)return loadRefs(s.ctx,p.imageUri,p.imageAsset);\n        return null;\n    }'''
new='''    private static Bitmap load(S s,Models.OrderItem it){\n        Bitmap b=loadRefs(s.ctx,it.imageUri,it.imageAsset);if(b!=null)return b;\n        Models.Product p=findProduct(s.products,it);\n        if(p!=null){b=loadRefs(s.ctx,p.imageUri,p.imageAsset);if(b!=null)return b;b=loadPrivate(s.ctx,p.code,p.id);if(b!=null)return b;}\n        return loadPrivate(s.ctx,it.code,it.productId);\n    }\n    private static Bitmap loadPrivate(Context c,String code,String id){\n        try{\n            File dir=new File(c.getFilesDir(),\"product_images\");if(!dir.isDirectory())return null;\n            String raw=!safe(code).isEmpty()?safe(code):safe(id);if(raw.isEmpty())return null;\n            String prefix=raw.replaceAll(\"[^a-zA-Z0-9._-]\",\"_\");File[] fs=dir.listFiles();File best=null;\n            if(fs!=null)for(File f:fs){if(!f.isFile()||f.length()<=0)continue;String n=f.getName();if(n.startsWith(prefix+\"_\")||n.equals(prefix+\".jpg\")||n.equals(prefix+\".jpeg\")||n.equals(prefix+\".png\")||n.equals(prefix+\".webp\")){if(best==null||f.lastModified()>best.lastModified())best=f;}}\n            if(best==null)return null;try(InputStream in=new FileInputStream(best)){return BitmapFactory.decodeStream(in);}\n        }catch(Exception e){return null;}\n    }'''
if old not in s: raise SystemExit('PDF load block not found')
s=s.replace(old,new)
p.write_text(s)
